def check_stop_download(
    signal: object, crawler: Crawler, request: Request, **kwargs: Any
) -> StopDownload | None:
    """Send the given signal and check if any of its handlers raised
    :exc:`~scrapy.exceptions.StopDownload`.

    Return the raised exception or ``None``.
    """
    signal_result = crawler.signals.send_catch_log(
        signal=signal,
        request=request,
        spider=crawler.spider,
        **kwargs,
    )

    def is_stop_download(result):
        return isinstance(result, Failure) and isinstance(result.value, StopDownload)

    for handler, result in signal_result:
        if is_stop_download(result):
            logger.debug(
                f"Download stopped for {request} from signal handler {handler.__qualname__}"
            )
            return result.value

    return None

def _update(self, step_size: int, gradient: Tensor, *args, **kwargs) -> Dict[str, Any]:
    """Update edge weights given gradient."""
    _, topk_edge_index = torch.topk(gradient, step_size)
    flip_edge_index = self.block_edge_index[:, topk_edge_index]
    flip_edge_weight = torch.ones_like(flip_edge_index[0], dtype=torch.float32)

    self.flipped_edges = torch.cat((self.flipped_edges, flip_edge_index), axis=-1)

    if self.is_undirected:
        flip_edge_index, flip_edge_weight = to_undirected(
            flip_edge_index, flip_edge_weight, num_nodes=self.num_nodes, reduce='mean'
        )

    edge_index, edge_weight = self._combine_edges(flip_edge_index, flip_edge_weight)
    self._filter_edges(edge_index, edge_weight)

    # Sample initial search space (Algorithm 2, line 3-4)
    self._sample_random_block(step_size)

    # Return debug information
    return {'number_positive_entries_in_gradient': (gradient > 0).sum().item()}

def _combine_edges(self, flip_edge_index, flip_edge_weight):
    edge_index = torch.cat(
        (self.edge_index.to(self.device), flip_edge_index.to(self.device)), dim=-1
    )
    edge_weight = torch.cat(
        (self.edge_weight.to(self.device), flip_edge_weight.to(self.device))
    )
    return coalesce(edge_index, edge_weight, num_nodes=self.num_nodes, reduce='sum')

def _filter_edges(self, edge_index, edge_weight):
    is_one_mask = torch.isclose(edge_weight, torch.tensor(1.))
    self.edge_index = edge_index[:, is_one_mask]
    self.edge_weight = edge_weight[is_one_mask]
    assert self.edge_index.size(1) == self.edge_weight.size(0)

def range_to_ndarray(rng: range) -> np.ndarray:
    """
    Cast a range object to ndarray.
    """
    # GH#30171 perf avoid realizing range as a list in np.array
    def try_arange(dtype):
        try:
            return np.arange(rng.start, rng.stop, rng.step, dtype=dtype)
        except OverflowError:
            return None

    arr = try_arange("int64")
    if arr is None:
        # GH#30173 handling for ranges that overflow int64
        if (rng.start >= 0 and rng.step > 0) or (rng.step < 0 <= rng.stop):
            arr = try_arange("uint64")
        if arr is None:
            arr = construct_1d_object_array_from_listlike(list(rng))

    return arr

def _is_retryable_exception(exc: Exception, status_code) -> bool:
    """Return True if an exception is likely to succeed when retried."""
    if status_code is not None:
        return status_code == 429 or status_code >= 500

    # Network/transport exceptions.
    return _is_network_exception(exc)

def _is_network_exception(exc: Exception) -> bool:
    """Check if the exception is a network-related exception."""
    try:
        from openai import APIConnectionError, APITimeoutError
        return isinstance(exc, (APIConnectionError, APITimeoutError))
    except ImportError:
        return False

def _decodeFromStream(self, s, strict):
    """Decode a complete DER SEQUENCE from a file."""

    self._seq = []

    # Fill up self.payload
    DerObject._decodeFromStream(self, s, strict)

    # Add one item at a time to self.seq, by scanning self.payload
    p = BytesIO_EOF(self.payload)
    while p.remaining_data() > 0:
        self._processPayloadItem(p, strict)

    self._validateSequenceLength()

def _processPayloadItem(self, p, strict):
    """Process a single item from the payload."""
    p.set_bookmark()
    der = DerObject()
    der._decodeFromStream(p, strict)

    # Parse INTEGERs differently
    if der._tag_octet != 0x02:
        self._seq.append(p.data_since_bookmark())
    else:
        derInt = DerInteger()
        data = p.data_since_bookmark()
        derInt.decode(data, strict=strict)
        self._seq.append(derInt.value)

def _validateSequenceLength(self):
    """Validate the length of the decoded sequence."""
    if self._nr_elements is not None:
        try:
            ok = len(self._seq) in self._nr_elements
        except TypeError:
            ok = len(self._seq) == self._nr_elements

        if not ok:
            raise ValueError("Unexpected number of members (%d)"
                             " in the sequence" % len(self._seq))

def request_from_dict(d: dict[str, Any], *, spider: Spider | None = None) -> Request:
    """Create a :class:`~scrapy.Request` object from a dict.

    If a spider is given, it will try to resolve the callbacks looking at the
    spider for methods with the same name.
    """
    request_cls: type[Request] = load_object(d["_class"]) if "_class" in d else Request
    kwargs = {key: value for key, value in d.items() if key in request_cls.attributes}

    def resolve_callback(callback_name: str):
        if d.get(callback_name) and spider:
            kwargs[callback_name] = _get_method(spider, d[callback_name])

    resolve_callback("callback")
    resolve_callback("errback")

    return request_cls(**kwargs)

def agg_or_apply_dict_like(
    self, op_name: Literal["agg", "apply"]
) -> DataFrame | Series:
    from pandas.core.groupby.generic import (
        DataFrameGroupBy,
        SeriesGroupBy,
    )

    assert op_name in ["agg", "apply"]

    obj = self.obj
    kwargs: dict[str, Any] = {}

    if op_name == "apply":
        kwargs["by_row"] = "_compat" if self.by_row else False

    if getattr(obj, "axis", 0) == 1:
        raise NotImplementedError("axis other than 0 is not supported")

    selected_obj = obj._selected_obj
    selection = obj._selection

    if isinstance(obj, (DataFrameGroupBy, SeriesGroupBy)):
        kwargs["engine"] = self.kwargs.get("engine", None)
        kwargs["engine_kwargs"] = self.kwargs.get("engine_kwargs", None)

    with com.temp_setattr(
        obj, "as_index", True, condition=hasattr(obj, "as_index")
    ):
        result_index, result_data = self.compute_dict_like(
            op_name, selected_obj, selection, kwargs
        )

    return self.wrap_results_dict_like(selected_obj, result_index, result_data)

def from_body(self, body: bytes) -> type[Response]:
    """Try to guess the appropriate response based on the body content.
    This method is a bit magic and could be improved in the future, but
    it's not meant to be used except for special cases where response types
    cannot be guess using more straightforward methods."""
    chunk = to_bytes(body[:5000])
    if not binary_is_text(chunk):
        return self.from_mimetype("application/octet-stream")

    lowercase_chunk = chunk.lower()
    if any(tag in lowercase_chunk for tag in [b"<html>", b"<!doctype html>"]):
        return self.from_mimetype("text/html")
    if b"<?xml" in lowercase_chunk:
        return self.from_mimetype("text/xml")

    return self.from_mimetype("text")

def forward(
    self,
    x: Union[Tensor, OptPairTensor],
    edge_index: Adj,
    edge_attr: OptTensor = None,
    size: Size = None,
) -> Tensor:
    x = (x, x) if isinstance(x, Tensor) else x

    # propagate_type: (x: OptPairTensor, edge_attr: OptTensor)
    out = self.propagate(edge_index, x=x, edge_attr=edge_attr, size=size)

    if x[1] is not None:
        out += (1 + self.eps) * x[1]

    return self.nn(out)

def execute(argv: list[str] | None = None, settings: Settings | None = None) -> None:
    argv = argv or sys.argv
    settings = settings or _initialize_settings()

    inproject = inside_project()
    cmds = _get_commands_dict(settings, inproject)
    cmdname = _pop_command_name(argv)

    if not cmdname:
        _print_commands(settings, inproject)
        sys.exit(0)

    if cmdname not in cmds:
        _print_unknown_command(settings, cmdname, inproject)
        sys.exit(2)

    cmd = cmds[cmdname]
    parser = _create_parser(cmdname, cmd)
    settings.setdict(cmd.default_settings, priority="command")
    cmd.settings = settings
    cmd.add_options(parser)
    opts, args = parser.parse_known_args(args=argv[1:])
    _run_print_help(parser, cmd.process_options, args, opts)

    cmd.crawler_process = _select_crawler_process(settings, cmd)
    _run_print_help(parser, _run_command, cmd, args, opts)
    sys.exit(cmd.exitcode)

def _initialize_settings() -> Settings:
    settings = get_project_settings()
    editor = os.environ.get("EDITOR")
    if editor:
        settings["EDITOR"] = editor
    return settings

def _create_parser(cmdname: str, cmd) -> ScrapyArgumentParser:
    return ScrapyArgumentParser(
        formatter_class=ScrapyHelpFormatter,
        usage=f"scrapy {cmdname} {cmd.syntax()}",
        conflict_handler="resolve",
        description=cmd.long_desc(),
    )

def _select_crawler_process(settings: Settings, cmd) -> CrawlerProcess:
    if (
        settings["TWISTED_REACTOR"] == _asyncio_reactor_path
        and not settings.getbool("FORCE_CRAWLER_PROCESS")
    ) or not settings.getbool("TWISTED_REACTOR_ENABLED"):
        return AsyncCrawlerProcess(settings)
    return CrawlerProcess(settings)

def _get_indexer_strict(self, key: Axes, axis_name: str_t) -> tuple[Index, np.ndarray]:
    """
    Analogue to get_indexer that raises if any elements are missing.
    """
    keyarr = self._prepare_keyarr(key)
    indexer = self._get_indexer(keyarr)
    self._raise_if_missing(keyarr, indexer, axis_name)
    keyarr = self._adjust_keyarr_for_freq(keyarr, key)
    return keyarr, indexer

def _prepare_keyarr(self, key: Axes) -> Index:
    if not isinstance(key, Index):
        key = com.asarray_tuplesafe(key)
    return key

def _get_indexer(self, keyarr: Index) -> np.ndarray:
    if self._index_as_unique:
        indexer = self.get_indexer_for(keyarr)  # pyright: ignore[reportArgumentType]
        if not isinstance(keyarr, Index):
            keyarr = ensure_index(keyarr)
            keyarr.name = self.name
    else:
        keyarr, indexer, _ = self._reindex_non_unique(keyarr)  # type: ignore[arg-type]  # pyright: ignore[reportArgumentType]
    return indexer

def _adjust_keyarr_for_freq(self, keyarr: Index, key: Axes) -> Index:
    keyarr = self.take(keyarr)
    if lib.is_np_dtype(keyarr.dtype, "mM") or isinstance(keyarr.dtype, DatetimeTZDtype):
        if isinstance(key, list) or (
            isinstance(key, type(self)) and key.freq is None  # type: ignore[attr-defined]
        ):
            keyarr = keyarr._with_freq(None)  # type: ignore[attr-defined]
    return keyarr

def _engine(
    self,
) -> libindex.IndexEngine | libindex.ExtensionEngine | libindex.MaskedIndexEngine:
    # For base class (object dtype) we get ObjectEngine
    dtype = self.dtype
    target_values = self._get_engine_target()

    if isinstance(dtype, ArrowDtype) and dtype.kind in "Mm":
        return self._handle_arrow_dtype()

    if isinstance(target_values, ExtensionArray):
        return self._handle_extension_array(target_values)

    return self._handle_standard_types(target_values, dtype)

def _handle_arrow_dtype(self):
    import pyarrow as pa

    values = self._values
    pa_type = values._pa_array.type  # type: ignore[union-attr]
    if pa.types.is_timestamp(pa_type):
        target_values = values._to_datetimearray()  # type: ignore[union-attr]
        return libindex.DatetimeEngine(target_values._ndarray)
    elif pa.types.is_duration(pa_type):
        target_values = values._to_timedeltaarray()  # type: ignore[union-attr]
        return libindex.TimedeltaEngine(target_values._ndarray)

def _handle_extension_array(self, target_values):
    if isinstance(target_values, (BaseMaskedArray, ArrowExtensionArray)):
        try:
            return _masked_engines[target_values.dtype.name](target_values)
        except KeyError:
            # Not supported yet e.g. decimal
            pass
    elif self._engine_type is libindex.ObjectEngine:
        return libindex.ExtensionEngine(target_values)

def _handle_standard_types(self, target_values, dtype):
    # to avoid a reference cycle, bind `target_values` to a local variable, so
    # `self` is not passed into the lambda.
    if target_values.dtype == bool:
        return libindex.BoolEngine(target_values)  # type: ignore[arg-type]
    elif target_values.dtype == np.complex64:
        return libindex.Complex64Engine(target_values)  # type: ignore[arg-type]
    elif target_values.dtype == np.complex128:
        return libindex.Complex128Engine(target_values)  # type: ignore[arg-type]
    elif needs_i8_conversion(dtype):
        # We need to keep M8/m8 dtype when initializing the Engine,
        #  but don't want to change _get_engine_target bc it is used
        #  elsewhere
        # error: Item "ExtensionArray" of "Union[ExtensionArray,
        # ndarray[Any, Any]]" has no attribute "_ndarray"  [union-attr]
        target_values = self._data._ndarray  # type: ignore[union-attr]
    elif isinstance(dtype, StringDtype):
        return libindex.StringObjectEngine(target_values, dtype.na_value)

    # error: Argument 1 to "ExtensionEngine" has incompatible type
    # "ndarray[Any, Any]"; expected "ExtensionArray"
    return self._engine_type(target_values)  # type: ignore[arg-type]

def deferred_from_coro(o: Awaitable[_T] | _T2) -> Deferred[_T] | _T2:
    """Convert a coroutine or other awaitable object into a Deferred,
    or return the object as is if it isn't a coroutine."""

    if isinstance(o, Deferred):
        return o

    if not inspect.isawaitable(o):
        return o

    if not is_asyncio_available():
        # wrapping the coroutine directly into a Deferred, this doesn't work correctly with coroutines
        # that use asyncio, e.g. "await asyncio.sleep(1)"
        return Deferred.fromCoroutine(cast("Coroutine[Deferred[Any], Any, _T]", o))

    # wrapping the coroutine into a Future and then into a Deferred, this requires AsyncioSelectorReactor
    return Deferred.fromFuture(asyncio.ensure_future(o))

def _process_spider_exception(
    self,
    response: Response,
    exception: Exception,
    start_index: int = 0,
) -> MutableAsyncChain[_T]:
    # don't handle _InvalidOutput exception
    if isinstance(exception, _InvalidOutput):
        raise exception

    method_list = islice(self.methods["process_spider_exception"], start_index, None)

    for method_index, method in enumerate(method_list, start=start_index):
        if method is None:
            continue

        result = self._invoke_method(method, response, exception)

        if isinstance(result, (Iterable, AsyncIterator)):
            # stop exception handling by handing control over to the
            # process_spider_output chain if an iterable has been returned
            if isinstance(result, Iterable):
                result = as_async_generator(result)
            return self._process_spider_output(response, result, method_index + 1)

        if result is not None:
            msg = (
                f"{global_object_name(method)} must return None "
                f"or an iterable, got {type(result)}"
            )
            raise _InvalidOutput(msg)

    # Every remaining middleware declined to handle the exception, so the
    # outer process_spider_output layers must let it through instead of
    # offering it to those middlewares again.
    with suppress(AttributeError):
        exception._spidermw_unhandled = True  # type: ignore[attr-defined]
    raise exception

def _invoke_method(self, method, response, exception):
    if method in self._mw_methods_requiring_spider:
        return method(response=response, exception=exception, spider=self._spider)
    return method(response=response, exception=exception)

def get_indptr(self) -> Tensor:
        r"""Returns the compressed index representation in case
        :class:`EdgeIndex` is sorted.
        """
        if self._indptr is None:
            if self.is_undirected and self._T_indptr is not None:
                return self._T_indptr

            dim = 0 if self.is_sorted_by_row else 1
            self._indptr = index2ptr(self._data[dim], self.get_sparse_size(dim))

        return self._indptr

def _truthy_value(self):
        # Fill values used for 'any'
        kind_truthy_map = {
            "f": 1.0,
            "i": 1,
            "u": 1
        }
        return kind_truthy_map.get(self.kind, True)

def _header_line(self):
    # Store line for reuse in _get_index_name
    if self.header is not None:
        return None

    try:
        return self._buffered_line()
    except StopIteration as err:
        if not self.names:
            raise EmptyDataError("No columns to parse from file") from err
        return self.names[:]

def _slice(
    input: EdgeIndex,
    dim: int,
    start: Optional[int] = None,
    end: Optional[int] = None,
    step: int = 1,
) -> Union[EdgeIndex, Tensor]:
    # Check for no-op condition
    if (start is None or start == 0 or start <= -input.size(dim)) and \
       (end is None or end > input.size(dim)) and step == 1:
        return input._shallow_copy()

    # Perform slicing
    out = aten.slice.Tensor(input._data, dim, start, end, step)

    # Handle special case for dim == 1 or dim == -1
    if dim in (1, -1):
        if step != 1:
            out = out.contiguous()

        out = EdgeIndex(out)
        out._sparse_size = input.sparse_size()

        # Maintain sort order based on step direction
        if step >= 0:
            out._sort_order = input._sort_order
        else:
            out._sort_order = SortOrder.COL if input._sort_order == SortOrder.ROW else SortOrder.ROW

    return out

def _get_block_for_concat_plan(
    mgr: BlockManager, bp: BlockPlacement, blkno: int, *, max_len: int
) -> Block:
    blk = mgr.blocks[blkno]

    if _is_full_block_slice(bp, blk):
        return blk

    ax0_blk_indexer = mgr.blklocs[bp.indexer]
    slc = lib.maybe_indices_to_slice(ax0_blk_indexer, max_len)

    return blk.slice_block_columns(slc) if isinstance(slc, slice) else blk.take_block_columns(slc)

def _is_full_block_slice(bp: BlockPlacement, blk: Block) -> bool:
    return len(bp) == len(blk.mgr_locs) and blk.mgr_locs.is_slice_like and blk.mgr_locs.as_slice.step == 1

def __rmatmul__(self, other) -> DataFrame:
    """
    Matrix multiplication using binary `@` operator.
    """
    try:
        return self.T.dot(np.transpose(other)).T
    except ValueError as err:
        if "shape mismatch" in str(err):
            # GH#21581 give exception message for original shapes
            msg = f"shapes {np.shape(other)} and {self.shape} not aligned"
            raise ValueError(msg) from err
        raise

def __contains__(self, key: str) -> bool:
    """
    check for existence of this key
    can match the exact pathname or the pathnm w/o the leading '/'
    """
    node = self.get_node(key)
    if node is None:
        return False
    name = node._v_pathname
    return key in (name, name[1:])

def queryables(self) -> dict[str, Any]:
    """return a dict of the kinds allowable columns for this object"""
    # mypy doesn't recognize DataFrame._AXIS_NAMES, so we re-write it here
    axis_names = {0: "index", 1: "columns"}

    # Create queryables from index_axes, non_index_axes, and values_axes
    index_queryables = [(a.cname, a) for a in self.index_axes]
    non_index_queryables = [(axis_names[axis], None) for axis, _ in self.non_index_axes]
    values_queryables = [
        (v.cname, v) for v in self.values_axes if v.name in set(self.data_columns)
    ]

    return dict(index_queryables + non_index_queryables + values_queryables)

def _build_impl(lib, postfix):
    from collections import namedtuple

    funcs = ("ghash", "ghash_expand", "ghash_destroy")
    GHASH_Imp = namedtuple('_GHash_Imp', funcs)

    def get_function(name):
        try:
            return getattr(lib, name + "_" + postfix)
        except AttributeError:
            return None

    imp_funcs = [get_function(func) for func in funcs]
    return GHASH_Imp(*imp_funcs)

def _extract_subject_public_key_info(x509_certificate):
    """Extract subjectPublicKeyInfo from a DER X.509 certificate."""

    certificate = DerSequence().decode(x509_certificate, nr_elements=3)
    tbs_certificate = DerSequence().decode(certificate[0], nr_elements=range(6, 11))

    def get_version_and_index(tbs_cert):
        try:
            tbs_cert[0] + 1  # Version not present
            return 1, 5
        except TypeError:
            version = DerInteger(explicit=0).decode(tbs_cert[0]).value
            if version not in (2, 3):
                raise ValueError("Incorrect X.509 certificate version")
            return version, 6

    _, index = get_version_and_index(tbs_certificate)
    return tbs_certificate[index]

def _maybe_infer_ndim(
    values: ArrayLike, placement: BlockPlacement, ndim: int | None
) -> int:
    """
    If `ndim` is not provided, infer it from placement and values.
    """
    if ndim is not None:
        return ndim

    # GH#38134 Block constructor now assumes ndim is not None
    if not isinstance(values.dtype, np.dtype):
        return 1 if len(placement) != 1 else 2

    return values.ndim

def unwrap(p8_private_key, passphrase=None):
    """Unwrap a private key from a PKCS#8 blob (clear or encrypted).

    Args:
      p8_private_key (bytes):
        The private key wrapped into a PKCS#8 container, DER encoded.

    Keyword Args:
      passphrase (byte string or string):
        The passphrase to use to decrypt the blob (if it is encrypted).

    Return:
      A tuple containing

       #. the algorithm identifier of the wrapped key (OID, dotted string)
       #. the private key (bytes, DER encoded)
       #. the associated parameters (bytes, DER encoded) or ``None``

    Raises:
      ValueError : if decoding fails
    """

    def decrypt_with_pbes(p8_private_key, passphrase):
        """Attempt decryption with PBES1 and PBES2."""
        try:
            return PBES1.decrypt(p8_private_key, passphrase), None
        except PbesError as e:
            error_str = "PBES1[%s]" % str(e)
        except ValueError:
            error_str = "PBES1[Invalid]"

        try:
            return PBES2.decrypt(p8_private_key, passphrase), None
        except PbesError as e:
            error_str += ",PBES2[%s]" % str(e)
        except ValueError:
            error_str += ",PBES2[Invalid]"

        return None, error_str

    if passphrase is not None:
        passphrase = tobytes(passphrase)
        p8_private_key, error_str = decrypt_with_pbes(p8_private_key, passphrase)
        if p8_private_key is None:
            raise ValueError("Error decoding PKCS#8 (%s)" % error_str)

    pk_info = DerSequence().decode(p8_private_key, nr_elements=(2, 3, 4, 5))
    if len(pk_info) == 2 and not passphrase:
        raise ValueError("Not a valid clear PKCS#8 structure "
                         "(maybe it is encrypted?)")

    if pk_info[0] not in (0, 1) or len(pk_info) not in (3, 4, 5):
        raise ValueError("Not a valid PrivateKeyInfo SEQUENCE")

    algo = DerSequence().decode(pk_info[1], nr_elements=(1, 2))
    algo_oid = DerObjectId().decode(algo[0]).value
    algo_params = None if len(algo) == 1 else algo[1]

    if algo_params is not None:
        try:
            DerNull().decode(algo_params)
            algo_params = None
        except:
            pass

    private_key = DerOctetString().decode(pk_info[2]).payload

    return (algo_oid, private_key, algo_params)

def _searchsorted_monotonic(self, label, side: Literal["left", "right"] = "left"):
    if self.is_monotonic_increasing and isinstance(label, (Timestamp, Timedelta)):
        label_unit = abbrev_to_npy_unit(label.unit)
        self_unit = abbrev_to_npy_unit(self.unit)

        if label_unit > self_unit:
            # For non-matching units we can safely round down (with side=right)
            # This is needed for GH#63262
            label = label.as_unit(self.unit) if side == "right" else label.ceil(self.unit).as_unit(self.unit)

    return super()._searchsorted_monotonic(label, side)

def to_bytes(
    text: str | bytes, encoding: str | None = None, errors: str = "strict"
) -> bytes:
    """Return the binary representation of ``text``. If ``text``
    is already a bytes object, return it as-is."""
    if isinstance(text, bytes):
        return text
    if isinstance(text, str):
        encoding = encoding or "utf-8"
        return text.encode(encoding, errors)
    raise TypeError(
        f"to_bytes must receive a str or bytes object, got {type(text).__name__}"
    )

def _get_form(
    response: TextResponse,
    formname: str | None,
    formid: str | None,
    formnumber: int,
    formxpath: str | None,
) -> FormElement:
    """Find the wanted form element within the given response."""
    root = response.selector.root
    forms = root.xpath("//form")
    if not forms:
        raise ValueError(f"No <form> element found in {response}")

    def find_form_by_attribute(attribute: str, value: str) -> FormElement | None:
        f = root.xpath(f'//form[@{attribute}="{value}"]')
        return cast("FormElement", f[0]) if f else None

    if formname is not None:
        form = find_form_by_attribute("name", formname)
        if form:
            return form

    if formid is not None:
        form = find_form_by_attribute("id", formid)
        if form:
            return form

    if formxpath is not None:
        nodes = root.xpath(formxpath)
        if nodes:
            el = nodes[0]
            while el is not None:
                if el.tag == "form":
                    return cast("FormElement", el)
                el = el.getparent()
        raise ValueError(f"No <form> element found with {formxpath}")

    try:
        return cast("FormElement", forms[formnumber])
    except IndexError:
        raise IndexError(f"Form number {formnumber} not found in {response}") from None

def generate_cipher(self, module, key_size, params):
    params_dict = dict(x.split("=") for x in params.split(" ")) if params else {}

    # Determine key
    key_multiplier = 2 if params_dict.get('ks') == "x2" else 1
    key = rng(key_multiplier * key_size)
    gen_tuple = [key]

    # Determine mode
    mode = params_dict.get("mode")
    if mode:
        mode_value = getattr(module, mode, None)
        if mode_value is None:
            raise ModeNotAvailable()
        gen_tuple.append(mode_value)

    # Determine IV/nonce
    iv_length = params_dict.get("iv") or params_dict.get("nonce")
    if iv_length:
        iv_length = module.block_size if iv_length == "bs" else int(iv_length)
        iv = rng(iv_length)
        gen_tuple.append(iv)

    # Handle CTR mode specifics
    le = params_dict.get("little_endian")
    if le is not None:
        le = le == "True"
        gen_tuple.pop()  # Remove iv from parameters
        ctr = Crypto.Util.Counter.new(
            module.block_size * 8,
            initial_value=bytes_to_long(iv),
            little_endian=le,
            allow_wraparound=True
        )
        gen_dict = {'counter': ctr}
    else:
        gen_dict = {}

    # Generate cipher
    return module.new(*gen_tuple, **gen_dict)

def c_uint8_ptr(data):
    """
    Casts the input data to a C uint8 pointer if possible.

    :param data: The data to be cast.
    :return: The casted data or raises a TypeError if the data type is unsupported.
    """
    if isinstance(data, _buffer_type):
        # This only works for cffi >= 1.7
        return ffi.cast(uint8_t_type, ffi.from_buffer(data))

    if byte_string(data) or isinstance(data, _Array):
        return data

    raise TypeError(f"Object type {type(data)} cannot be passed to C code")

def _agg_py_fallback(
    self, how: str, values: ArrayLike, ndim: int, alt: Callable
) -> ArrayLike:
    """
    Fallback to pure-python aggregation if _cython_operation raises
    NotImplementedError.
    """
    # We get here with a) EADtypes and b) object dtype
    assert alt is not None

    ser = self._create_series_from_values(values)

    try:
        res_values = self._grouper.agg_series(ser, alt)
    except Exception as err:
        msg = f"agg function failed [how->{how},dtype->{ser.dtype}]"
        raise type(err)(msg) from err

    res_values = self._cast_result_values(res_values, ser.dtype)

    return ensure_block_shape(res_values, ndim=ndim)

def _create_series_from_values(self, values: ArrayLike) -> Series:
    if values.ndim == 1:
        return Series(values, copy=False)
    else:
        df = DataFrame(values.T, dtype=values.dtype)
        assert df.shape[1] == 1
        return df.iloc[:, 0]

def _cast_result_values(self, res_values: ArrayLike, dtype: DtypeObj) -> ArrayLike:
    if dtype == object:
        return res_values.astype(object, copy=False)
    elif is_string_dtype(dtype):
        string_array_cls = dtype.construct_array_type()  # type: ignore[union-attr]
        return string_array_cls._from_sequence(res_values, dtype=dtype)
    return res_values

def _get_request_cookies(self, jar: CookieJar, request: Request) -> Sequence[Cookie]:
    """
    Extract cookies from the Request.cookies attribute
    """
    if not request.cookies:
        return ()

    cookies: Iterable[VerboseCookie] = _to_verbose_cookies(request.cookies)
    for cookie in cookies:
        cookie.setdefault("secure", urlparse_cached(request).scheme == "https")

    formatted_cookies = (
        self._format_cookie(c, request) for c in cookies
    )
    filtered_cookies = filter(None, formatted_cookies)
    response = Response(request.url, headers={"Set-Cookie": filtered_cookies})

    return jar.make_cookies(response, request)

def load_pycryptodome_raw_lib(name, cdecl):
    """Load a shared library and return a handle to it.

    @name,  the name of the library expressed as a PyCryptodome module,
            for instance Crypto.Cipher._raw_cbc.

    @cdecl, the C function declarations.
    """
    dir_comps, basename = name.rsplit(".", 1)
    attempts = []

    for ext in extension_suffixes:
        filename = basename + ext
        full_name = pycryptodome_filename(dir_comps.split("."), filename)

        if os.path.isfile(full_name):
            try:
                return load_lib(full_name, cdecl)
            except OSError as exp:
                attempts.append(f"Cannot load '{filename}': {exp}")
        else:
            attempts.append(f"Not found '{filename}'")

    raise OSError(f"Cannot load native module '{name}': {', '.join(attempts)}")

def _col_idx_to_axis_idx(self, col_idx: int) -> int:
    """Return the index of the axis where the column at col_idx should be plotted"""
    if isinstance(self.subplots, list):
        # Subplots is a list: some columns will be grouped together in the same ax
        return self._find_group_index(col_idx)
    # subplots is True: one ax per column
    return col_idx

def _find_group_index(self, col_idx: int) -> int:
    """Helper function to find the group index for a given column index."""
    return next(
        group_idx
        for group_idx, group in enumerate(self.subplots)
        if col_idx in group
    )

async def create_artifacts(state: QAGenerationState) -> Dict[str, Any]:
    logger.info('Create artifacts for task %s', state['task_id'])
    client = state.get('client')
    use_artifact = state.get('use_artifact')
    logger.debug('use_artifact? %s', use_artifact)

    if not use_artifact:
        return {'top_artifacts': None}

    segments = state.get('segments', [])
    text_artifacts = state.get('text_artifacts') or get_text_artifacts(segments, client)
    logger.info('text artifacts: %d', len(text_artifacts))

    try:
        parts = state.get('parts', 3)
        splits = split_segments(segments, parts=parts)
        artifacts_str_splits = [
            ArtifactExtractor(client).format_artifacts_for_prompt(
                ArtifactExtractor(client).get_top_artifacts_for_qa(
                    text_artifacts, top_k=5, use_llm_ranking=True
                )
            )
            for _ in splits
        ]
        return {'top_artifacts': artifacts_str_splits}
    except Exception as e:
        logger.warning('create_artifacts failed %s', e)
        return {'top_artifacts': None}

def test_compilation(program, extra_cc_options=None, extra_libraries=None, msg=''):
    """Test if a certain C program can be compiled."""
    import os
    import sys
    from distutils import ccompiler
    from distutils.errors import CCompilerError

    def create_temp_file(directory, filename, content):
        if not os.path.exists(directory):
            os.makedirs(directory)
        filepath = os.path.join(directory, filename)
        with open(filepath, 'w') as f:
            f.write(content)
        return filepath

    def mute_output():
        if not (debug or os.name == 'nt'):
            old_stdout = os.dup(sys.stdout.fileno())
            old_stderr = os.dup(sys.stderr.fileno())
            dev_null = open(os.devnull, "w")
            os.dup2(dev_null.fileno(), sys.stdout.fileno())
            os.dup2(dev_null.fileno(), sys.stderr.fileno())
            return old_stdout, old_stderr, dev_null
        return None, None, None

    def restore_output(old_stdout, old_stderr, dev_null):
        if not (debug or os.name == 'nt'):
            if old_stdout is not None:
                os.dup2(old_stdout, sys.stdout.fileno())
            if old_stderr is not None:
                os.dup2(old_stderr, sys.stderr.fileno())
            if dev_null is not None:
                dev_null.close()

    def cleanup_files(files):
        for f in files:
            try:
                os.remove(f)
            except OSError:
                pass

    build_dir = "build"
    source_file = create_temp_file(build_dir, "test1.c", program)
    executable_file = os.path.join(build_dir, "test1.out")

    debug = bool(os.environ.get('PYCRYPTODOME_DEBUG', None))
    if msg:
        print(f"Testing support for {msg}")

    old_stdout, old_stderr, dev_null = mute_output()

    try:
        compiler = ccompiler.new_compiler()
        distutils.sysconfig.customize_compiler(compiler)

        extra_linker_options = ["/MANIFEST"] if compiler.compiler_type == 'msvc' else []
        if compiler.compiler_type == 'unix':
            compiler.set_executables(linker_exe=compiler.compiler)

        objects = compiler.compile([source_file], extra_postargs=extra_cc_options)
        compiler.link_executable(objects, executable_file, libraries=extra_libraries,
                                 extra_preargs=extra_linker_options)
        result = True
    except (CCompilerError, OSError):
        result = False

    cleanup_files(objects + [source_file, executable_file])
    restore_output(old_stdout, old_stderr, dev_null)

    if msg:
        print(f"Target does{' not' if not result else ''} support {msg}")

    return result

def _make_ssl_context(settings: BaseSettings) -> ssl.SSLContext:
    """Create an :class:`ssl.SSLContext` instance according to the settings.

    It's intended to be used in an HTTPS download handler.
    """
    tls_min_ver, tls_max_ver = _get_tls_version_limits(
        settings, _STDLIB_VERSION_MAP.__getitem__
    )
    ciphers_setting: str | None = settings["DOWNLOADER_CLIENT_TLS_CIPHERS"]
    verify_setting = settings.getbool("DOWNLOAD_VERIFY_CERTIFICATES")

    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    ctx.check_hostname = verify_setting
    ctx.verify_mode = ssl.CERT_REQUIRED if verify_setting else ssl.CERT_NONE

    if verify_setting:
        ctx.load_default_certs()

    if tls_min_ver is not None:
        ctx.minimum_version = tls_min_ver
    if tls_max_ver is not None:
        ctx.maximum_version = tls_max_ver
    if ciphers_setting:
        ctx.set_ciphers(ciphers_setting)
    if keylog_filename := _get_keylog_filename():
        ctx.keylog_filename = keylog_filename

    return ctx

def setup(app):
    def check_python_version():
        if python_version[0] < 3:
            logger.error("Python 2 is not supported with sphinx_rtd_theme, update to Python 3.")

    def check_html4_writer():
        if app.config.html4_writer:
            logger.error("'html4_writer' is not supported with sphinx_rtd_theme.")

    def setup_jquery_extension():
        if sphinx_version >= (6, 0, 0):
            app.setup_extension("sphinxcontrib.jquery")
            from sphinxcontrib.jquery import add_js_files as jquery_add_js_files
            jquery_add_js_files(app, app.config)

    def register_theme():
        app.add_html_theme('sphinx_rtd_theme', path.abspath(path.dirname(__file__)))

    def add_message_catalog():
        rtd_locale_path = path.join(path.abspath(path.dirname(__file__)), 'locale')
        app.add_message_catalog('sphinx', rtd_locale_path)

    def configure_app():
        app.connect('config-inited', config_initiated)
        app.config.html_permalinks_icon = "\uf0c1"
        app.connect("html-page-context", extend_html_context)

    check_python_version()
    app.require_sphinx('6.0')
    check_html4_writer()
    setup_jquery_extension()
    register_theme()
    add_message_catalog()
    configure_app()

    return {'parallel_read_safe': True, 'parallel_write_safe': True}

def get_complement_subgraph(self) -> 'Explanation':
    r"""Returns the induced subgraph, in which all nodes and edges with any
    attribution are masked out.
    """
    def process_mask(mask, condition):
        return mask.sum(dim=-1) == 0 if condition else None

    node_mask = process_mask(self.get('node_mask'), self.get('node_mask') is not None)
    edge_mask = self.get('edge_mask') == 0 if self.get('edge_mask') is not None else None

    return self._apply_masks(node_mask, edge_mask)

def _do_tdes_test(self, file_name):
    test_vectors = load_test_vectors(
        ("Cipher", "TDES"),
        file_name,
        "TDES CBC KAT",
        {"count": lambda x: int(x)}
    )
    if test_vectors is None:
        return

    direction = None
    for tv in test_vectors:
        if is_string(tv):
            direction = tv
            continue

        self.description = tv.desc
        cipher = self._initialize_cipher(tv)

        if direction == "[ENCRYPT]":
            self.assertEqual(cipher.encrypt(tv.plaintext), tv.ciphertext)
        elif direction == "[DECRYPT]":
            self.assertEqual(cipher.decrypt(tv.ciphertext), tv.plaintext)

def _initialize_cipher(self, tv):
    if hasattr(tv, "keys"):
        return DES.new(tv.keys, self.des_mode, tv.iv)
    key = tv.key1 + tv.key2 + (tv.key3 if tv.key1 != tv.key3 else "")
    return DES3.new(key, self.des3_mode, tv.iv)

def _create_base_cipher(dict_parameters):
    """This method instantiates and returns a smart pointer to
    a low-level base cipher. It will absorb named parameters in
    the process."""

    def pop_param(param_name, default=None, required=True):
        try:
            return dict_parameters.pop(param_name)
        except KeyError:
            if required:
                raise TypeError(f"Missing EKSBlowfish parameter: {param_name}")
            return default

    key = pop_param("key")
    salt = pop_param("salt")
    cost = pop_param("cost")
    invert = pop_param("invert", default=True, required=False)

    if len(key) not in key_size:
        raise ValueError(f"Incorrect EKSBlowfish key length ({len(key)} bytes)")

    start_operation = _raw_blowfish_lib.EKSBlowfish_start_operation
    stop_operation = _raw_blowfish_lib.EKSBlowfish_stop_operation

    void_p = VoidPointer()
    result = start_operation(
        c_uint8_ptr(key),
        c_size_t(len(key)),
        c_uint8_ptr(salt),
        c_size_t(len(salt)),
        c_uint(cost),
        c_uint(int(invert)),
        void_p.address_of()
    )
    if result:
        raise ValueError(f"Error {result:X} while instantiating the EKSBlowfish cipher")

    return SmartPointer(void_p.get(), stop_operation)

def _nbytes(self, deep: bool = False) -> int:
    """
    return the number of bytes in the underlying data
    deeply introspect the level data if deep=True

    include the engine hashtable

    *this is in internal routine*

    """
    # for implementations with no useful getsizeof (PyPy)
    objsize = 24

    def calculate_memory_usage(items, deep=False):
        return sum(item.memory_usage(deep=deep) for item in items)

    def calculate_nbytes(items):
        return sum(item.nbytes for item in items)

    def calculate_getsizeof(items, default_size):
        return sum(getsizeof(item, default_size) for item in items)

    level_nbytes = calculate_memory_usage(self.levels, deep)
    label_nbytes = calculate_nbytes(self.codes)
    names_nbytes = calculate_getsizeof(self.names, objsize)

    result = level_nbytes + label_nbytes + names_nbytes

    # include our engine hashtable, only if it's already cached
    if "_engine" in self._cache:
        result += self._engine.sizeof(deep=deep)

    return result

def infer_filename(self) -> str | None:
    """
    If an explicit archive_name is not given, we still want the file inside the zip
    file not to be named something.tar, because that causes confusion (GH39465).
    """
    if self.name is None:
        return None

    filename = Path(self.name)
    suffixes_to_strip = {".tar": 1, ".tar.gz": 2, ".tar.bz2": 2, ".tar.xz": 2}
    suffix_count = suffixes_to_strip.get(filename.suffix, 0)

    for _ in range(suffix_count):
        filename = filename.with_suffix("")

    return filename.name

def _read_strls(self) -> None:
    self._path_or_buf.seek(self._seek_strls)
    self.GSO = {"0": ""}

    while self._path_or_buf.read(3) == b"GSO":
        v_o = self._read_v_o()
        typ = self._read_uint8()
        length = self._read_uint32()
        va = self._path_or_buf.read(length)
        decoded_va = self._decode_va(va, typ)
        self.GSO[str(v_o)] = decoded_va

def _read_v_o(self) -> int:
    if self._format_version == 117:
        return self._read_uint64()
    buf = self._path_or_buf.read(12)
    v_size = 2 if self._format_version == 118 else 3
    if self._byteorder == "<":
        buf = buf[0:v_size] + buf[4:(12 - v_size)]
    else:
        buf = buf[4 - v_size:4] + buf[(4 + v_size):]
    return struct.unpack(f"{self._byteorder}Q", buf)[0]

def _decode_va(self, va: bytes, typ: int) -> str:
    if typ == 130:
        return va[0:-1].decode(self._encoding)
    return str(va)

def set_dataset_info(dataset):
    r"""Set global dataset information.

    Args:
        dataset: PyG dataset object

    """
    # get dim_in and dim_out
    cfg.share.dim_in = getattr(dataset._data.x, 'shape', [1])[1] if hasattr(dataset._data.x, 'shape') else 1

    try:
        if cfg.dataset.task_type == 'classification':
            cfg.share.dim_out = torch.unique(dataset._data.y).shape[0]
        else:
            cfg.share.dim_out = dataset._data.y.shape[1]
    except Exception:
        cfg.share.dim_out = 1

    # count number of dataset splits
    cfg.share.num_splits = 1 + any('val' in key for key in dataset._data.keys()) + any('test' in key for key in dataset._data.keys())
